/*
 * The ROM images compiled into the binary, generated by
 * tools/xroar/embed-roms.py.
 *
 * XRoar resolves machine and cartridge ROMs by basename against its -rompath,
 * so nothing has to be patched into the core: paths.c materialises this table
 * into the user's ROM directory on first start and points -rompath at it. An
 * entry is skipped when a file of that name is already there, so a ROM the
 * user imported always wins over the compiled-in one.
 *
 * Two classes:
 *
 *   is_system = 0  HDB-DOS DW3 (hdbdw3bck, hdbdw3bc3). Freely redistributable,
 *                  and the FujiNet link does not work without them, so they
 *                  are always present.
 *   is_system = 1  Color BASIC, Extended Color BASIC and Super Extended Color
 *                  BASIC. Tandy/Microware copyright, present only in a
 *                  WITH_COCO_ROMS=ON build, which must not be redistributed.
 *
 * coco_embedded_system_roms is 1 in exactly that build; a frontend can use it
 * to decide whether to offer "Import BIOS...". See COMPLIANCE.md.
 *
 * Copyright (C) 2026 Thomas Cherryhomes
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

#ifndef COCO_ROMS_EMBEDDED_H
#define COCO_ROMS_EMBEDDED_H

#include <stddef.h>

typedef struct {
    const char *name;            /* exact filename, e.g. "bas13.rom" */
    const unsigned char *data;
    size_t size;                 /* generated from sizeof, so size_t exactly */
    int is_system;               /* 1 = Tandy/Microware copyright */
} coco_embedded_rom;

extern const coco_embedded_rom coco_embedded_roms[];
extern const int coco_embedded_rom_count;
extern const int coco_embedded_system_roms;

#endif /* COCO_ROMS_EMBEDDED_H */
